"proposal": {
  "capability": "deployment.set-probes",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "payments",
    "name": "payments-worker",
    "uid": "uid-deployment-payments-worker"
  },
  "params": {
    "container": "app",
    "liveness": {
      "timeoutSeconds": 5
    }
  },
  "expected_effect": "Allow 5s for app to respond to liveness probe before restarting",
  "rationale": "Current 2s timeout fails before app (which takes 46s to start) can respond. Increasing timeout aligns with observed startup duration.",
